#include "Monstey_NavCompactOptimizerCore.hpp"
#include "Monstey_NavigationBoundaryQuery.hpp"
#include "Monstey_Core.hpp"
#include "Monstey_Havok.hpp"
#include <algorithm>
#include <array>
#include <bit>
#include <cmath>
#include <iostream>
#include <numeric>
#include <random>
using namespace Monstey;
namespace {
using B=Monstey_NavigationAabb;using H=Monstey_NavHierarchy;
void Check(bool ok,const char*message){Monstey_Require(ok,message);}
void Validate(const H&t,std::size_t count){Check(t.leaf_count==count&&t.root>0,"Core leaf count/root differs");const auto p=Monstey_NavPreorderHierarchy(t);std::vector<std::uint32_t>ids;for(std::size_t i=1;i<p.nodes.size();++i){const auto&node=p.nodes[i];if(node.child0){for(const auto child:{node.child0,node.child1_or_payload}){const auto&c=p.nodes[child];Check(c.parent==i,"Core child-parent disagreement");for(unsigned axis=0;axis<3;++axis)Check(c.bounds.minimum[axis]>=node.bounds.minimum[axis]&&c.bounds.maximum[axis]<=node.bounds.maximum[axis],"Core child not within parent");}}else ids.push_back(node.child1_or_payload);}std::sort(ids.begin(),ids.end());Check(ids.size()==count,"Core leaves lost/duplicated");for(std::size_t i=0;i<count;++i)Check(ids[i]==i,"Core payload identity differs");}
bool Intersects(const B&a,const B&b){for(unsigned axis=0;axis<3;++axis)if(a.minimum[axis]>b.maximum[axis]||b.minimum[axis]>a.maximum[axis])return false;return true;}
std::vector<B>Bounds(const H&t){std::vector<B>result(t.leaf_count);for(const auto&node:t.nodes)if(!node.child0&&node.child1_or_payload<t.leaf_count)result[node.child1_or_payload]=node.bounds;return result;}
void QueryCoverage(const H&t,const std::vector<B>&original,std::mt19937&rng,unsigned cases){const auto packed=Monstey_NavPackPreorder(Monstey_NavPreorderHierarchy(t));std::uniform_real_distribution<float>f(-110,110),w(0,35);for(unsigned n=0;n<cases;++n){B query{};for(unsigned axis=0;axis<3;++axis){query.minimum[axis]=f(rng);query.maximum[axis]=query.minimum[axis]+w(rng);}const auto hits=Monstey_NavigationCompactTreeQuery({packed.nodes,packed.bounds},query);std::vector<bool>seen(original.size());for(const auto id:hits){Check(id<original.size()&&!seen[id],"Compact tree repeated/outside payload");seen[id]=true;}for(std::size_t i=0;i<original.size();++i)if(Intersects(query,original[i]))Check(seen[i],"Cooked tree omitted a true face-bound intersection");}}
Monstey_Bytes Records(Monstey_Havok&graph,std::size_t mesh,std::string_view field,std::size_t stride){const auto array=graph.Field(mesh,field);Monstey_Bytes out;for(const auto id:graph.Node(array).elements){const auto&record=graph.Node(id).original_storage;Check(record.size()==stride,"Actual native record stride differs");out.insert(out.end(),record.begin(),record.end());}return out;}
}
int wmain(int argc,wchar_t**argv){try{Check(argc==2||argc==3,"NEW_REPORT [SOURCE_HKAI]");unsigned groups=0,cases=0;const B equal{{1,2,3,0},{2,3,4,0}};
const std::array<B,3>same{equal,equal,equal};const auto t=Monstey_NavOptimizeHierarchyCore(Monstey_NavInsertHierarchy(same));Validate(t,3);Check(t.root==5&&t.nodes[5].child0==2&&t.nodes[5].child1_or_payload==3&&t.nodes[3].child0==4&&t.nodes[3].child1_or_payload==1,"Native three-equal-box free-list/sort/work order");++groups;++cases;
std::mt19937 rng(0x74803216);std::uniform_real_distribution<float>f(-100,100),w(.01f,12);unsigned trees=0,queries=0;for(unsigned count:{3u,4u,8u,16u,17u,18u,31u,32u,33u,64u,97u,152u})for(unsigned repeat=0;repeat<8;++repeat){std::vector<B>boxes;for(unsigned n=0;n<count;++n){B box{};for(unsigned axis=0;axis<3;++axis){box.minimum[axis]=f(rng);box.maximum[axis]=box.minimum[axis]+w(rng);}boxes.push_back(box);}const auto original=Monstey_NavInsertHierarchy(boxes);const auto optimized=Monstey_NavOptimizeHierarchyCore(original);Validate(optimized,count);QueryCoverage(optimized,boxes,rng,64);queries+=64;++trees;}groups+=2;cases+=trees+queries;
const std::array<B,2>two{equal,{{3,2,3,0},{4,3,4,0}}};const auto before=Monstey_NavInsertHierarchy(two),after=Monstey_NavOptimizeHierarchyCore(before);Check(before.root==after.root&&before.nodes.size()==after.nodes.size(),"Native optimizer early-return root");for(std::size_t i=0;i<before.nodes.size();++i)Check(before.nodes[i].parent==after.nodes[i].parent&&before.nodes[i].child0==after.nodes[i].child0&&before.nodes[i].child1_or_payload==after.nodes[i].child1_or_payload,"Native <=2 early-return topology");++groups;++cases;
Monstey_Json actual=Monstey_Json();if(argc==3){const std::filesystem::path source=argv[2];const auto bytes=Monstey_ReadFile(source);const auto hash=Monstey_HashSha256(bytes);Check(hash=="b9fb6380798b09110a8db133ea6139e17db88ec5cad123fc6aa1fe1b038008ee","Actual Seregost source differs");Check(Monstey_U32(bytes,0)==0x49414b48&&Monstey_U32(bytes,4)==3&&Monstey_U32(bytes,12)==bytes.size()-20,"Actual HKAI3 envelope differs");Monstey_Havok graph(std::span(bytes).subspan(16,bytes.size()-20));const auto meshes=graph.Objects("hkaiNavMesh");Check(meshes.size()==1,"Expected one actual source mesh");const auto faces=Records(graph,meshes[0],"faces",16),edges=Records(graph,meshes[0],"edges",20),vertices=Records(graph,meshes[0],"vertices",16);const auto inserted=Monstey_NavInsertFaceHierarchy(faces,edges,vertices);const auto core=Monstey_NavOptimizeHierarchyCore(inserted);Validate(core,152);const auto packed=Monstey_NavPackPreorder(Monstey_NavPreorderHierarchy(core));const auto leafBounds=Bounds(inserted);for(const auto&box:leafBounds){const auto hits=Monstey_NavigationCompactTreeQuery({packed.nodes,packed.bounds},box);for(std::size_t i=0;i<leafBounds.size();++i)if(Intersects(box,leafBounds[i]))Check(std::find(hits.begin(),hits.end(),static_cast<std::uint32_t>(i))!=hits.end(),"Actual cooked tree omits true face bound");}Check(Monstey_HashSha256(source)==hash,"Actual source changed");actual=Monstey_Json::object({{"source_sha256",hash},{"faces",faces.size()/16},{"edges",edges.size()/20},{"vertices",vertices.size()/16},{"nodes",packed.nodes.size()/6},{"compact_sha256_before_final_rotations",Monstey_HashSha256(packed.nodes)},{"runtime_verified",false}});++groups;cases+=153;}
Monstey_WriteNewText(argv[1],Monstey_Json::object({{"status","PASS"},{"scope","native optimizer core only; finalization tested separately"},{"groups",groups},{"cases",cases},{"random_hierarchies",trees},{"conservative_queries",queries},{"actual",actual},{"original_program_executed",false}}).dump(2)+"\n");std::cout<<"PASS "<<groups<<" optimizer core groups / "<<cases<<" cases\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
